create temporary view user_item_raw_${grass_region_without_quote} as
select FILTER(scenario_tags,
              value -> value in (
                  'dpm reporting object you may also like module User Scenario business line Rcmd'
                  ,'dpm reporting object post purchase module User Scenario business line Rcmd'
                  ,'dpm module Daily Discover business line Homepage'
                  )
       ) as scenario_tags
     ,FILTER(source1_scenario_tags,
             value -> value in (
                'dpm reporting object you may also like module User Scenario business line Rcmd'
                 ,'dpm reporting object post purchase module User Scenario business line Rcmd'
                 ,'dpm module Daily Discover business line Homepage'
                 )
      ) as source1_scenario_tags
     ,FILTER(source2_scenario_tags,
             value -> value in (
                'dpm reporting object you may also like module User Scenario business line Rcmd'
                 ,'dpm reporting object post purchase module User Scenario business line Rcmd'
                 ,'dpm module Daily Discover business line Homepage'
                 )
      ) as source2_scenario_tags
     ,feature_detail
     ,source1_feature_detail
     ,source2_feature_detail
     ,operation
     ,user_id
     ,exp_group_ids
     ,coalesce(traffic_vsku_item_id,item_id) as item_id
     ,coalesce(cast(is_ads as string), 'false') as is_ads
     ,imp_cnt
     ,click_cnt
     ,ppv_cnt
     ,cart_cnt
     ,order_cnt
     ,gmv
     ,pc2_gmv
from srdi_mart.dwm_sr_data_warehouse_platform_user_item
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation in ('impression','click','ppv','cart','order')
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW user_item_union_${grass_region_without_quote} as
select scenario_tags
     ,feature_detail
     ,user_id
     ,exp_group_ids
     ,item_id
     ,is_ads
     ,sum(imp_cnt) imp_cnt
     ,sum(click_cnt) click_cnt
     ,sum(ppv_cnt) ppv_cnt
     ,sum(cart_cnt) cart_cnt
     ,sum(order_cnt) order_cnt
     ,sum(gmv) gmv
     ,sum(pc2_gmv) pc2_gmv
from user_item_raw_${grass_region_without_quote}
where size(scenario_tags)>=1
group by 1,2,3,4,5,6

union ALL

select source1_scenario_tags as scenario_tags
     ,source1_feature_detail as feature_detail
     ,user_id
     ,exp_group_ids
     ,item_id
     ,is_ads
     ,0 as imp_cnt
     ,0 as click_cnt
     ,sum(ppv_cnt) ppv_cnt
     ,sum(cart_cnt) cart_cnt
     ,sum(order_cnt) order_cnt
     ,sum(gmv) gmv
     ,sum(pc2_gmv) pc2_gmv
from user_item_raw_${grass_region_without_quote}
where COALESCE(source1_feature_detail, '') != ''
and source1_feature_detail != feature_detail
and size(source1_scenario_tags)>=1
and operation in ('ppv','cart','order')
group by 1,2,3,4,5,6

union all

select source2_scenario_tags as scenario_tags
     ,source2_feature_detail as feature_detail
     ,user_id
     ,exp_group_ids
     ,item_id
     ,is_ads
     ,0 as imp_cnt
     ,0 as click_cnt
     ,sum(ppv_cnt) ppv_cnt
     ,sum(cart_cnt) cart_cnt
     ,sum(order_cnt) order_cnt
     ,sum(gmv) gmv
     ,sum(pc2_gmv) pc2_gmv
from user_item_raw_${grass_region_without_quote}
where COALESCE(source2_feature_detail, '') != ''
AND source2_feature_detail != source1_feature_detail
AND source2_feature_detail != feature_detail
and size(source2_scenario_tags)>=1
and operation in ('ppv','cart','order')
group by 1,2,3,4,5,6
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_filter_${grass_region_without_quote} as
select  user_id
     ,exp_group_id
from    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where   grass_region in (${grass_region})
  and   local_date = ${local_date}
  and   is_assignment_log = 1
  and   is_rcmd_whitelist = 1
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW base_exp_${grass_region_without_quote} as
select scenario_tags
     ,coalesce(ELEMENT_AT(SPLIT(feature_detail, '-'), -1),'others') AS target_type
     ,a.user_id
     ,b.exp_group_id
     ,item_id
     ,is_ads
     ,sum(imp_cnt) imp_cnt
     ,sum(click_cnt) click_cnt
     ,sum(ppv_cnt) ppv_cnt
     ,sum(cart_cnt) cart_cnt
     ,sum(order_cnt) order_cnt
     ,sum(gmv) gmv
     ,sum(pc2_gmv) pc2_gmv
from user_item_union_${grass_region_without_quote} a
inner join exp_filter_${grass_region_without_quote} b
on a.user_id = b.user_id
group by 1,2,3,4,5,6
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW item_tag_${grass_region_without_quote} as
select
    item_id
     ,case when datediff(${local_date},cast(item_create_datetime as date)) <= 30 then '0d_30d'
           when datediff(${local_date},cast(item_create_datetime as date)) <=90 then '30d_90d'
    end as item_tag
from srdi_mart.dim_sr_data_warehouse_item
where grass_region in (${grass_region})
and local_date = ${local_date}
and datediff(${local_date},cast(item_create_datetime as date)) <=90
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW vitem_${grass_region_without_quote} as
select vitem_id
    from srdi_mart.dim_sr_data_warehouse_vsku_vitem
where grass_region in (${grass_region})
  and local_date = ${local_date}
GROUP BY 1
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW base_exp_explode_${grass_region_without_quote} as
select scenario_tag
     , if(grouping(target_type)=1,'__ALL__',target_type) target_type
     , if(grouping(is_ads)=1,'__ALL__',is_ads) is_ads
     , if(grouping(is_vsku)=1,'__ALL__',is_vsku) is_vsku
     , user_id
     , exp_group_id
     ,SUM(scene_imp_cnt) AS scene_imp_cnt
     ,SUM(scene_click_cnt) AS scene_click_cnt
     ,SUM(scene_ppv_cnt) AS scene_ppv_cnt
     ,SUM(scene_cart_cnt) AS scene_cart_cnt
     ,SUM(scene_order_cnt) AS scene_order_cnt
     ,SUM(scene_gmv) AS scene_gmv
     ,SUM(scene_pc2_gmv) AS scene_pc2_gmv

     ,SUM(new_item_30d_imp_cnt) AS new_item_30d_imp_cnt
     ,SUM(new_item_30d_click_cnt) AS new_item_30d_click_cnt
     ,SUM(new_item_30d_ppv_cnt) AS new_item_30d_ppv_cnt
     ,SUM(new_item_30d_cart_cnt) AS new_item_30d_cart_cnt
     ,SUM(new_item_30d_order_cnt) AS new_item_30d_order_cnt
     ,SUM(new_item_30d_gmv) AS new_item_30d_gmv
     ,SUM(new_item_30d_pc2_gmv) AS new_item_30d_pc2_gmv

     ,SUM(new_item_90d_imp_cnt) AS new_item_90d_imp_cnt
     ,SUM(new_item_90d_click_cnt) AS new_item_90d_click_cnt
     ,SUM(new_item_90d_ppv_cnt) AS new_item_90d_ppv_cnt
     ,SUM(new_item_90d_cart_cnt) AS new_item_90d_cart_cnt
     ,SUM(new_item_90d_order_cnt) AS new_item_90d_order_cnt
     ,SUM(new_item_90d_gmv) AS new_item_90d_gmv
     ,SUM(new_item_90d_pc2_gmv) AS new_item_90d_pc2_gmv
from (
    SELECT scenario_tags
           , target_type
           , user_id
           , exp_group_id
           , is_ads
           , if(c.vitem_id is not null, 1, 0) is_vsku
           , sum(imp_cnt) scene_imp_cnt
           , sum(click_cnt) scene_click_cnt
           , sum(ppv_cnt) scene_ppv_cnt
           , sum(cart_cnt) scene_cart_cnt
           , sum(order_cnt) scene_order_cnt
           , sum(gmv) scene_gmv
           , sum(pc2_gmv) scene_pc2_gmv

           , sum(case when item_tag = '0d_30d' then imp_cnt else 0 end) new_item_30d_imp_cnt
           , sum(case when item_tag = '0d_30d' then click_cnt else 0 end) new_item_30d_click_cnt
           , sum(case when item_tag = '0d_30d' then ppv_cnt else 0 end) new_item_30d_ppv_cnt
           , sum(case when item_tag = '0d_30d' then cart_cnt else 0 end) new_item_30d_cart_cnt
           , sum(case when item_tag = '0d_30d' then order_cnt else 0 end) new_item_30d_order_cnt
           , sum(case when item_tag = '0d_30d' then gmv else 0 end) new_item_30d_gmv
           , sum(case when item_tag = '0d_30d' then pc2_gmv else 0 end) new_item_30d_pc2_gmv

           , sum(case when item_tag is not null then imp_cnt else 0 end) new_item_90d_imp_cnt
           , sum(case when item_tag is not null then click_cnt else 0 end) new_item_90d_click_cnt
           , sum(case when item_tag is not null then ppv_cnt else 0 end) new_item_90d_ppv_cnt
           , sum(case when item_tag is not null then cart_cnt else 0 end) new_item_90d_cart_cnt
           , sum(case when item_tag is not null then order_cnt else 0 end) new_item_90d_order_cnt
           , sum(case when item_tag is not null then gmv else 0 end) new_item_90d_gmv
           , sum(case when item_tag is not null then pc2_gmv else 0 end) new_item_90d_pc2_gmv
    FROM base_exp_${grass_region_without_quote} a
    LEFT JOIN item_tag_${grass_region_without_quote} b
    ON a.item_id = b.item_id
    left join vitem_${grass_region_without_quote} c
    on a.item_id = c.vitem_id
    group by 1,2,3,4,5,6
)x
LATERAL VIEW EXPLODE(scenario_tags) AS scenario_tag
group by GROUPING SETS (
    (user_id, exp_group_id, scenario_tag, target_type, is_ads),
    (user_id, exp_group_id, scenario_tag, target_type),
    (user_id, exp_group_id, scenario_tag, is_ads),
    (user_id, exp_group_id, scenario_tag),
    (user_id, exp_group_id, scenario_tag, target_type, is_ads, is_vsku),
    (user_id, exp_group_id, scenario_tag, target_type, is_vsku),
    (user_id, exp_group_id, scenario_tag, is_ads, is_vsku),
    (user_id, exp_group_id, scenario_tag, is_vsku)
    )
;
